// Diagnosis.js
import React from 'react';

const diagnosticData = [
  { id: 1, name: 'Blood Pressure', result: 'Normal', date: '2024-09-01' },
  { id: 2, name: 'Blood Sugar', result: 'High', date: '2024-09-02' },
  { id: 3, name: 'Cholesterol', result: 'Normal', date: '2024-09-03' },
];

export default function Diagnosis(){
  return (
    <div className="diagnosis-container">
      <h2>Diagnostic Results</h2>
      <ul>
        {diagnosticData.map((diagnosis) => (
          <li key={diagnosis.id}>
            <strong>{diagnosis.name}</strong>: {diagnosis.result} (Date: {diagnosis.date})
          </li>
        ))}
      </ul>
    </div>
  );
};
